using System.Net.Http.Headers; using System.Text; using System.Text.Json;
ApplicationConfiguration.Initialize(); Application.Run(new GeneratorForm());
sealed class GeneratorForm:Form { readonly TextBox token=new(){UseSystemPasswordChar=true}, count=new(){Text="1"}, output=new(){Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both}; readonly Label status=new(){Text="等待操作",AutoSize=true,ForeColor=Color.FromArgb(140,190,235)}; readonly Button generate=new(){Text="生成卡密",Height=46};
public GeneratorForm(){Text="wtlyf 卡密生成器";ClientSize=new(720,560);MinimumSize=new(620,480);BackColor=Color.FromArgb(6,12,27);ForeColor=Color.White;Font=new("Microsoft YaHei UI",11);Padding=new(28);var title=new Label{Text="WTLYF / LICENSE GENERATOR",Font=new("Segoe UI",22,FontStyle.Bold),AutoSize=true,ForeColor=Color.FromArgb(95,217,255)};var grid=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=8,ColumnCount=1};grid.RowStyles.Add(new(SizeType.AutoSize));grid.Controls.Add(title);grid.Controls.Add(new Label{Text="管理员令牌",AutoSize=true,Margin=new(0,28,0,6)});token.Dock=DockStyle.Top;grid.Controls.Add(token);grid.Controls.Add(new Label{Text="生成数量（1-100）",AutoSize=true,Margin=new(0,16,0,6)});count.Dock=DockStyle.Top;grid.Controls.Add(count);generate.BackColor=Color.FromArgb(51,105,210);generate.FlatStyle=FlatStyle.Flat;generate.Margin=new(0,18,0,10);grid.Controls.Add(generate);grid.Controls.Add(status);output.Dock=DockStyle.Fill;output.BackColor=Color.FromArgb(13,24,47);output.ForeColor=Color.White;grid.Controls.Add(output);Controls.Add(grid);generate.Click+=async(_,_)=>await Run();}
async Task Run(){generate.Enabled=false;status.Text="正在安全生成…";try{using var client=new HttpClient();client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",token.Text.Trim());var body=JsonSerializer.Serialize(new{count=int.Parse(count.Text)});var res=await client.PostAsync("https://wtlyf-license-center.creamy-bowl-8571.chatgpt.site/api/admin/generate",new StringContent(body,Encoding.UTF8,"application/json"));var text=await res.Content.ReadAsStringAsync();using var json=JsonDocument.Parse(text);if(!res.IsSuccessStatusCode)throw new Exception(json.RootElement.GetProperty("message").GetString());output.Text=string.Join(Environment.NewLine,json.RootElement.GetProperty("codes").EnumerateArray().Select(x=>x.GetString()));status.Text="生成成功，仅本次明文显示";}catch(Exception e){status.Text="生成失败："+e.Message;}finally{generate.Enabled=true;}}
}

